-- The client Onboarding visibility boundary reads its already-authorized submission summaries.
-- app_list_form_submissions retains module, current-Tenant, exact-client/company and
-- current-access checks through can_read_form_submission, and redacts inaccessible pointers.
-- CREATE OR REPLACE retains the existing function owner and execute privileges.
create or replace function private.client_support_operation_allowed(p_path text,p_method text)
returns boolean language sql immutable set search_path='' as $$
  select case when regexp_replace(p_path,'^(/rest/v1)?/','') like 'rpc/%'
    then substring(regexp_replace(p_path,'^(/rest/v1)?/','') from 5)=any(array['app_get_client_support_context','app_current_tenant_membership','app_current_user_permissions','app_current_user_modules','app_require_module_access','app_get_client_account_context','app_get_my_profile','app_get_runtime_white_label_configuration','app_list_my_client_projects','app_get_my_client_project','app_get_my_order_start','app_request_my_order_start','app_reconcile_my_order_start','app_my_intake_version_available','app_get_project_conversation','app_get_published_form_schema','app_list_assigned_forms','app_list_form_submissions','app_forms_work_enabled','app_get_form_assignment_history','app_get_assigned_form_schema','app_get_assigned_form_service_labels','app_submit_form','app_get_intake_follow_up','app_get_intake_draft','app_save_intake_draft','app_prepare_intake_file','app_finish_intake_file','app_get_intake_file','app_get_form_submission_pdf','app_get_form_submission','app_list_ticket_summaries','app_get_ticket_detail_with_avatars','app_get_order_conversation','app_send_order_message','app_reply_to_order_message','app_toggle_order_message_reaction','app_reply_to_ticket','app_reply_to_ticket_message','app_toggle_ticket_message_reaction','app_create_ticket','app_prepare_ticket_attachment','app_send_ticket_message_with_attachment','app_get_ticket_attachment_download','app_set_client_conversation_presence','app_list_my_notifications','app_mark_notification_read','app_mark_all_notifications_read','app_list_my_client_reports','app_get_my_client_report','app_mark_client_report_read','app_count_my_unread_reports','app_invoices_work_enabled','app_get_invoice_financials','app_list_invoice_items','app_get_wf_card_settings','app_store_purchase_projects_enabled','app_pay_invoice_with_wallet','app_purchase_service_with_balance','app_get_company_wallet','app_list_my_wallet_history','app_subscriptions_work_enabled','app_list_subscription_summaries','app_get_subscription_detail','app_record_store_interest']::text[])
    else p_method in ('GET','HEAD') and regexp_replace(p_path,'^(/rest/v1)?/','')=any(array['profiles','services','service_folders','invoices','companies','wf_card_memberships']) end;
$$;
